## Objective
Create a utility class that formats search results for fzf and handles the interaction.

## Implementation Steps

### 1. Create file
Create `src/lib/fzf-pipe.ts`:

```typescript
import { spawn } from "node:child_process";
import { Readable } from "node:stream";

interface FzfResult {
  selected: boolean;
  filePath: string;
  lineNumber: number;
}

interface SearchResultForFzf {
  path: string;
  startLine: number;
  endLine: number;
  score: number;
  preview: string; // First line of content
}

export class FzfPipe {
  /**
   * Check if fzf is installed and available
   */
  static async isAvailable(): Promise<boolean> {
    try {
      await execAsync("which fzf");
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Format search results for fzf display
   * Format: "path:line-end (score%) | preview text"
   */
  formatResults(results: SearchResultForFzf[]): string[] {
    return results.map(r => 
      `${r.path}:${r.startLine}-${r.endLine} (${(r.score * 100).toFixed(1)}%) | ${r.preview.slice(0, 80)}`
    );
  }

  /**
   * Pipe results to fzf and get selection
   */
  async selectWithFzf(results: SearchResultForFzf[]): Promise<FzfResult | null> {
    const lines = this.formatResults(results);

    return new Promise((resolve, reject) => {
      const fzf = spawn("fzf", [
        "--ansi",
        "--preview-window", "right:50%",
        "--preview", "cat {1} | head -100",  // Preview file content
        "--delimiter", ":",
        "--nth", "1,2",  // Search in path and line number
      ], {
        stdio: ["pipe", "pipe", "inherit"]
      });

      // Write results to fzf stdin
      const input = lines.join("\n");
      fzf.stdin.write(input);
      fzf.stdin.end();

      let output = "";
      fzf.stdout.on("data", (data) => {
        output += data.toString();
      });

      fzf.on("close", (code) => {
        if (code === 0 && output.trim()) {
          // Parse selection: "path:line-end (score%) | preview"
          const match = output.match(/^([^:]+):(\d+)-/);
          if (match) {
            resolve({
              selected: true,
              filePath: match[1],
              lineNumber: parseInt(match[2], 10)
            });
          }
        }
        resolve(null);  // No selection or cancelled
      });

      fzf.on("error", reject);
    });
  }

  /**
   * Open file in $EDITOR at specific line
   */
  async openInEditor(filePath: string, line: number): Promise<void> {
    const editor = process.env.EDITOR || process.env.VISUAL || "vi";

    // Most editors support +line syntax
    const args = [
      `+${line}`,  // vim, nvim, nano, emacs
      filePath
    ];

    // Special handling for some editors
    if (editor.includes("code")) {
      // VS Code uses -g file:line
      args[0] = "-g";
      args[1] = `${filePath}:${line}`;
    }

    spawn(editor, args, {
      stdio: "inherit",
      detached: false
    });
  }
}
```

